out.push("\n\n### 14.1 原生 JavaScript 实现\n\n```html\n<button\n  id=\"filter-toggle\"\n  type=\"button\"\n  aria-expanded=\"false\"\n  aria-controls=\"filter-panel\"\n>\n  Filters\n</button>\n\n<div id=\"filter-panel\" hidden>\n  <!-- Filter controls -->\n</div>\n```\n\n```javascript\nconst button = document.querySelector('#filter-toggle');\nconst panel = document.querySelector('#filter-panel');\n\nlet isOpen = false;\n\nfunction render() {\n  if (\n    !isOpen &&\n    panel.contains(document.activeElement)\n  ) {\n    button.focus();\n  }\n\n  button.setAttribute(\n    'aria-expanded',\n    String(isOpen)\n  );\n\n  panel.hidden = !isOpen;\n}\n\nfunction setOpen(nextState) {\n  isOpen = nextState;\n\n  render();\n}\n\nbutton.addEventListener('click', () => {\n  setOpen(!isOpen);\n});\n\nrender();\n```\n\n甚至可以直接通过 ARIA 状态控制 CSS：\n\n```css\n.filter-toggle[aria-expanded=\"true\"] .icon {\n  transform: rotate(180deg);\n}\n```\n\n这样就不需要额外维护一个表示相同状态的 `.is-expanded` class。\n\n### 14.2 React 中的实现\n\n```jsx\nfunction Disclosure({ children }) {\n  const [isOpen, setIsOpen] = useState(false);\n  const panelId = useId();\n\n  return (\n    <>\n      <button\n        type=\"button\"\n        aria-expanded={isOpen}\n        aria-controls={panelId}\n        onClick={() => setIsOpen(v => !v)}\n      >\n        Filters\n      </button>\n\n      <div id={panelId} hidden={!isOpen}>\n        {children}\n      </div>\n    </>\n  );\n}\n```\n\n在 React 中，ARIA 属性同样应该由组件的实际业务状态推导。\n\n这个示例只包含基本展开行为。如果组件还允许通过外部事件关闭，并且关闭时焦点可能位于内部，则需要补充上一课学习的焦点恢复机制。\n\n---\n\n## 15. ARIA 的五条经典使用原则\n\n早期 W3C Using ARIA 指南中的五条原则非常值得记忆。目前这份历史文档已停止维护，保留了四条规则；这里将可访问名称要求一起整理为日常开发的五条工程原则。");
